package com.certpath;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class CertPathApplicationTests{@Autowired MockMvc mvc;@Test void publicCertificationListWorks()throws Exception{mvc.perform(get("/api/certifications")).andExpect(status().isOk()).andExpect(jsonPath("$.data.content").isArray());}@Test void swaggerEntryIsPublic()throws Exception{mvc.perform(get("/swagger-ui.html")).andExpect(status().is3xxRedirection());}@Test void protectedEndpointRejectsAnonymous()throws Exception{mvc.perform(get("/api/me/certifications")).andExpect(status().isForbidden());}}
